<?php
require_once __DIR__.'/config/auth.php';petcare_require_admin();require_once __DIR__.'/config/db.php';
$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 petcare_check_csrf();$tipo=$_POST['tipo']??'';$categoria=trim($_POST['categoria']??'');$descricao=trim($_POST['descricao']??'');$valor=filter_var($_POST['valor']??'',FILTER_VALIDATE_FLOAT);$forma=trim($_POST['forma_pagamento']??'');
 if(!in_array($tipo,['entrada','saida'],true)||$valor===false||$valor<=0||$categoria===''||$descricao==='')$erro='Preencha os dados e informe valor positivo.';
 else{$q=$pdo->prepare('INSERT INTO financeiro(tipo,categoria,descricao,valor,forma_pagamento) VALUES(?,?,?,?,?)');$q->execute([$tipo,$categoria,$descricao,$valor,$forma?:null]);header('Location: admin_financeiro.php');exit;}
}
$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$mes))$mes=date('Y-m');
$ini=$mes.'-01';$fim=date('Y-m-d',strtotime($ini.' +1 month'));
$q=$pdo->prepare('SELECT tipo,COALESCE(SUM(valor),0) total FROM financeiro WHERE data_lancamento>=? AND data_lancamento<? GROUP BY tipo');$q->execute([$ini,$fim]);$totais=['entrada'=>0,'saida'=>0];foreach($q as $r)$totais[$r['tipo']]=(float)$r['total'];
$q=$pdo->prepare('SELECT * FROM financeiro WHERE data_lancamento>=? AND data_lancamento<? ORDER BY data_lancamento DESC,id DESC LIMIT 100');$q->execute([$ini,$fim]);$rows=$q->fetchAll();
$q=$pdo->query('SELECT data_lancamento,tipo,valor FROM financeiro ORDER BY data_lancamento DESC LIMIT 10000');$serie=[];
foreach($q as $r){$chave=substr((string)$r['data_lancamento'],0,7);if(!isset($serie[$chave]))$serie[$chave]=['entrada'=>0,'saida'=>0];$serie[$chave][$r['tipo']]+=(float)$r['valor'];}ksort($serie);$serie=array_slice($serie,-12,null,true);
$pageTitle='Gestão financeira';require __DIR__.'/includes/header.php';?>
