<div class="form-grid" style="margin-bottom:16px"><div class="card"><h3>Entradas</h3><h2>R$ <?=number_format($totais['entrada'],2,',','.')?></h2></div><div class="card"><h3>Saídas</h3><h2>R$ <?=number_format($totais['saida'],2,',','.')?></h2></div><div class="card"><h3>Resultado</h3><h2>R$ <?=number_format($totais['entrada']-$totais['saida'],2,',','.')?></h2></div></div>
<div class="card" style="margin-bottom:16px"><h2>Comparativo mensal</h2><div style="display:flex;align-items:end;gap:14px;min-height:190px;overflow-x:auto">
