<div style="min-width:78px;text-align:center"><div style="height:145px;display:flex;align-items:end;justify-content:center;gap:5px"><div title="Receitas: R$ <?=number_format($v['entrada']??0,2,',','.')?>" style="background:#6258d9;width:25px;height:<?=max(2,round(140*($v['entrada']??0)/$max))?>px"></div><div title="Despesas: R$ <?=number_format($v['saida']??0,2,',','.')?>" style="background:#e68a54;width:25px;height:<?=max(2,round(140*($v['saida']??0)/$max))?>px"></div></div><small><?=htmlspecialchars($mesSerie)?></small></div><?php endforeach;?></div><p><small>■ Roxo: receitas &nbsp; ■ Laranja: despesas</small></p></div>
