<?php $pend=$pdo->query("SELECT a.id,a.servico,a.data_agendamento,an.nome animal FROM agendamentos a JOIN animais an ON an.id=a.animal_id LEFT JOIN atendimento_fechamentos af ON af.agendamento_id=a.id LEFT JOIN planos_utilizacoes pu ON pu.agendamento_id=a.id WHERE a.status='Concluído' AND af.agendamento_id IS NULL AND pu.id IS NULL ORDER BY a.data_agendamento DESC LIMIT 30")->fetchAll();foreach($pend as $v):?><tr><td><?=htmlspecialchars($v['animal'])?></td><td><?=htmlspecialchars($v['servico'])?></td><td><?=htmlspecialchars($v['data_agendamento'])?></td><td><a class="btn primary" href="<?= PETCARE_BASE_URL ?>/atendimento/pagamento.php?id=<?=$v['id']?>">Registrar pagamento</a></td></tr><?php endforeach;?><?php if(!$pend):?><tr><td colspan="4">Nenhum serviço pendente de recebimento.</td></tr><?php endif;?></tbody></table></div>
<div class="card form-card" style="margin-bottom:16px"><h2>Novo lançamento manual</h2><?php if($erro):?><p style="color:#b42318"><?=htmlspecialchars($erro)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(petcare_csrf_token())?>"><div class="form-grid"><div class="field"><label>Tipo</label><select name="tipo"><option value="saida">Despesa</option><option value="entrada">Receita</option></select></div><div class="field"><label>Categoria</label><input name="categoria" required placeholder="Ex.: Aluguel, produto, venda"></div><div class="field"><label>Descrição</label><input name="descricao" required></div><div class="field"><label>Valor (use ponto decimal)</label><input type="number" step="0.01" min="0.01" name="valor" required></div><div class="field"><label>Forma de pagamento</label><select name="forma_pagamento"><option value="Pix">Pix</option><option value="Dinheiro">Dinheiro</option><option value="Cartão">Cartão</option><option value="Transferência">Transferência</option><option value="Outro">Outro</option></select></div></div><div class="actions"><button class="btn primary">Registrar lançamento</button></div></form></div>
<div class="card table-wrap"><h2>Movimentações do período</h2><table class="table"><thead><tr><th>Data</th><th>Tipo</th><th>Categoria</th><th>Descrição</th><th>Pagamento</th><th>Valor</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['data_lancamento'])?></td><td><?=htmlspecialchars($r['tipo'])?></td><td><?=htmlspecialchars($r['categoria'])?></td><td><?=htmlspecialchars($r['descricao'])?></td><td><?=htmlspecialchars($r['forma_pagamento']??'—')?></td><td>R$ <?=number_format($r['valor'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Sem movimentações neste período.</td></tr><?php endif;?></tbody></table></div>
